func mobileAPIProtectionDecodeURLList(raw json.RawMessage) (mobileAPIProtectionURLListOwnedList, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if len(raw) == 0 {
		return mobileAPIProtectionURLListOwnedList{}, diagnostics
	}
	if mobileAPIProtectionJSONNull(raw) {
		diagnostics.AddError("Malformed mobile API protection result", "The successful API result contained null url_list instead of an array.")
		return mobileAPIProtectionURLListOwnedList{}, diagnostics
	}
	var rawItems []json.RawMessage
	if err := json.Unmarshal(raw, &rawItems); err != nil {
		diagnostics.AddError("Malformed mobile API protection result", "The successful API result contained a non-array url_list value.")
		return mobileAPIProtectionURLListOwnedList{}, diagnostics
	}
	if len(rawItems) > mobileAPIProtectionURLListMaxItems {
		diagnostics.AddError("Malformed mobile API protection result", fmt.Sprintf("The successful API result contained more than %d url_list items.", mobileAPIProtectionURLListMaxItems))
		return mobileAPIProtectionURLListOwnedList{}, diagnostics
	}

	items := make([]mobileAPIProtectionURLListWireItem, 0, len(rawItems))
	seen := make(map[int]struct{}, len(rawItems))
	knownKeys := map[string]struct{}{
		"idx": {},
		"url": {},
	}
	for position, rawItem := range rawItems {
		location := fmt.Sprintf("url_list item %d", position+1)
		var object map[string]json.RawMessage
		if err := json.Unmarshal(rawItem, &object); err != nil || object == nil {
			diagnostics.AddError("Malformed mobile API protection result", location+" was not an object.")
			continue
		}
		unknown := make([]string, 0)
		for key := range object {
			if _, ok := knownKeys[key]; !ok {
				unknown = append(unknown, key)
			}
		}
		sort.Strings(unknown)
		if len(unknown) != 0 {
			diagnostics.AddError("Unknown mobile API protection item field", location+" contained unsupported keys: "+strings.Join(unknown, ", ")+".")
			continue
		}
		index, ok := mobileAPIProtectionDecodeIndex(object["idx"], location, "int", &diagnostics)
		if !ok {
			continue
		}
		if _, duplicate := seen[index]; duplicate {
			diagnostics.AddError("Malformed mobile API protection result", fmt.Sprintf("%s used duplicate idx %d.", location, index))
			continue
		}
		seen[index] = struct{}{}
		item := mobileAPIProtectionURLListWireItem{Index: index}
		urlValue, ok := mobileAPIProtectionDecodeRequiredString(object["url"], location+" url", &diagnostics)
		if !ok {
			continue
		}
		mobileAPIProtectionValidateString(location, " url", urlValue, 0, 255, &diagnostics)
		item.URL = urlValue
		items = append(items, item)
	}
	if diagnostics.HasError() {
		return mobileAPIProtectionURLListOwnedList{}, diagnostics
	}
	sort.Slice(items, func(i, j int) bool { return items[i].Index < items[j].Index })
	return mobileAPIProtectionURLListOwnedList{Set: true, Items: items}, diagnostics
}

func mobileAPIProtectionURLListWrapperValue(owned mobileAPIProtectionURLListOwnedList, subItemOwnedMasks map[string][]bool) (types.Object, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if !owned.Set {
		return types.ObjectNull(mobileAPIProtectionURLListWrapperAttributeTypes), diagnostics
	}
	elements := make([]attr.Value, 0, len(owned.Items))
	for _, item := range owned.Items {
		objectValues := map[string]attr.Value{}
		objectValues["url"] = types.StringValue(item.URL)
		object, objectDiagnostics := types.ObjectValue(mobileAPIProtectionURLListItemAttributeTypes, objectValues)
		diagnostics.Append(objectDiagnostics...)
		elements = append(elements, object)
	}
	list, listDiagnostics := types.ListValue(types.ObjectType{AttrTypes: mobileAPIProtectionURLListItemAttributeTypes}, elements)
	diagnostics.Append(listDiagnostics...)
	wrapper, wrapperDiagnostics := types.ObjectValue(mobileAPIProtectionURLListWrapperAttributeTypes, map[string]attr.Value{"item": list})
	diagnostics.Append(wrapperDiagnostics...)
	return wrapper, diagnostics
}
func mobileAPIProtectionDecodeIndex(raw json.RawMessage, location string, idxKind string, diagnostics *diag.Diagnostics) (int, bool) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || mobileAPIProtectionJSONNull(trimmed) {
		diagnostics.AddError("Malformed mobile API protection result", location+" did not contain a non-null integer idx.")
		return 0, false
	}
	if trimmed[0] != '-' && (trimmed[0] < '0' || trimmed[0] > '9') {
		diagnostics.AddError("Malformed mobile API protection result", location+" contained a non-integer idx.")
		return 0, false
	}
	var number json.Number
	if err := json.Unmarshal(trimmed, &number); err != nil {
		diagnostics.AddError("Malformed mobile API protection result", location+" contained a non-integer idx.")
		return 0, false
	}
	value64, err := number.Int64()
	if err != nil || value64 <= 0 || int64(int(value64)) != value64 {
		diagnostics.AddError("Malformed mobile API protection result", location+" contained an idx that was not a positive integer.")
		return 0, false
	}
	return int(value64), true
}
