func mobileAPIProtectionOwnership(ctx context.Context, template bool, ownership wafmodule.OwnershipContext) (mobileAPIProtectionOwnershipSet, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if template {
		return mobileAPIProtectionOwnershipSet{URLList: false}, diagnostics
	}
	if ownership.Source == wafmodule.OwnershipImported {
		return mobileAPIProtectionOwnershipSet{URLList: true}, diagnostics
	}
	configsValue, ownershipDiagnostics := wafmodule.OwnershipConfigs(ctx, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() || configsValue.IsNull() {
		return mobileAPIProtectionOwnershipSet{URLList: false}, diagnostics
	}
	if configsValue.IsUnknown() {
		diagnostics.AddError("Unknown mobile API protection ownership", "The configs ownership state was unknown while flattening.")
		return mobileAPIProtectionOwnershipSet{URLList: false}, diagnostics
	}
	var configs mobileAPIProtectionConfigsModel
	diagnostics.Append(configsValue.As(ctx, &configs, basetypes.ObjectAsOptions{})...)
	return mobileAPIProtectionOwnershipSet{URLList: !configs.URLList.IsNull()}, diagnostics
}
func mobileAPIProtectionValidateString(location, label, value string, minimum, maximum int, diagnostics *diag.Diagnostics) {
	if minimum > 0 && utf8.RuneCountInString(value) < minimum {
		diagnostics.AddError("Invalid mobile API protection item", fmt.Sprintf("%s%s must be at least %d UTF-8 characters.", location, label, minimum))
	}
	if maximum > 0 && utf8.RuneCountInString(value) > maximum {
		diagnostics.AddError("Invalid mobile API protection item", fmt.Sprintf("%s%s exceeds %d UTF-8 characters.", location, label, maximum))
	}
}
func mobileAPIProtectionConfigActionValid(value string) bool {
	_, ok := mobileAPIProtectionConfigActionValues[value]
	return ok
}

func mobileAPIProtectionJSONNull(raw json.RawMessage) bool {
	return bytes.Equal(bytes.TrimSpace(raw), []byte("null"))
}

// RejectItemNullUnlessNullable reports a malformed-result diagnostic when a
// collection-item field is present in the remote response as an explicit JSON
// null but the pinned schema does not mark the field nullable. A missing key
// is not rejected here (optional omission is handled by the decode helpers).
func mobileAPIProtectionRejectItemNullUnlessNullable(object map[string]json.RawMessage, key string, allowNull bool, location string, diagnostics *diag.Diagnostics) {
	raw, ok := object[key]
	if !ok {
		return
	}
	if mobileAPIProtectionJSONNull(raw) && !allowNull {
		diagnostics.AddError("Malformed mobile API protection result", location+" "+key+" was null, which the pinned schema does not mark nullable.")
	}
}
